String exchange(List<int> lst1, List<int> lst2) {
  if (lst1.length != lst2.length || !lst1.containsAll(lst2)) return "NO";

  int count = 0;
  for (int i = 0; i < lst1.length; ++i) {
    if (lst1[i] == lst2[i]) {
      count++;
    }
  }

  int swapsNeeded = 0;
  for (int i = 0; i < lst1.length && count < lst1.length; ++i) {
    while (count < lst1.length) {
      bool foundMatch = false;

      // Try to find a match from the end of the list first
      for (int j = lst1.length - 1; j > i; --j) {
        if (lst1[j] == lst2[i] && lst1[i] != lst1[j]) {
          // Swap elements and increment counts
          final temp = lst1[i];
          lst1[i] = lst1[j];
          lst1[j] = temp;

          count += 2;
          swapsNeeded++;
          foundMatch = true;
          break;
        }
      }

      // If no swap was possible in this iteration, check next position
      if (!foundMatch) {
        count++;
      }
    }
  }

  return swapsNeeded % 2 == 0 ? "YES" : "NO";
}

