  String bestExtension = "";

  for (var extension in extensions) {
    var score = extension.split('')..where((char) => char == 'l' || char.toLowerCase() == 'o').length + 
                 extension.length;

    if (score > maxScore) {
      maxScore = score;
      bestExtension = extension;
    } else if (score == maxScore && extension.compareTo(bestExtension) < 0) {
      bestExtension = extension;
    }
  }

  return '$className.$bestExtension';
}

String strongestExtension(String className, List<String> extensions) {
  final Map<int, String> map = {};

  for (final extension in extensions) {
    final length = extension.split('').length;
    if (!map.containsKey(length)) {
      map[length] = extension;
    } else {
      map[length] = max(map[length], extension);
    }
  }

  int maxLength = -1;
  String longestWord = "";

  map.forEach((key, value) {
    if (maxLength < key.length || maxLength == key && value.compareTo(longestWord) > 0) {
      maxLength = key;
      longestWord = value;
    }
  });

  return '$className.$longestWord';
}

